// ─── Dados de entrada ─────────────────────────────────────────────────────────
const dados        = $('When Executed by Another Workflow').first().json;
const inputJson    = $input.first()?.json || {};
const list         = Array.isArray(inputJson.items) ? inputJson.items : $input.all().map(item => item.json);
const todosEventos = list.filter(e => e && (e.summary || e.start));

// ─── Campos extraídos ─────────────────────────────────────────────────────────
const nomeCliente    = (dados.nome_cliente || dados.nome || dados.cliente || '').trim();
const primeiroNome   = nomeCliente.toLowerCase().split(' ')[0];
const procedimento   = (dados.procedimento || dados.servico || dados.serviço || '').trim();
let   dataHoraInicio = (dados.data_hora_inicio || dados.inicio || dados.start || '').trim();
const duracaoMinutos = Number(dados.duracao_minutos || dados.duracao || 0);
const telefone       = String(dados.telefone_cliente || dados.telefone || dados.numero || '').replace(/\D/g, '');
const observacoes    = dados.observacoes || dados.obs || '';

// ─── Limite máximo de agendamentos ──────────────────────────────────────────
const LIMITE_MAXIMO = 3;

const eventosDoCliente = todosEventos.filter(evento => {
  const summary     = (evento.summary     || '').toLowerCase();
  const description = (evento.description || '').toLowerCase();
  const temTelefone = telefone.length     >= 8 && description.includes(telefone);
  const temNome     = primeiroNome.length >= 3 && summary.includes(primeiroNome);
  return temTelefone || temNome;
});

if (eventosDoCliente.length >= LIMITE_MAXIMO) {
  return {
    json: {
      sucesso: false,
      motivo: `Você já possui ${eventosDoCliente.length} agendamentos ativos. O limite máximo é de ${LIMITE_MAXIMO} por cliente.`
    }
  };
}

// ─── Validação de campos obrigatórios ─────────────────────────────────────────
const erros = [];
if (!nomeCliente    || nomeCliente.length  < 2) erros.push('Nome do cliente ausente ou inválido.');
if (!procedimento   || procedimento.length < 2) erros.push('Procedimento/serviço ausente.');
if (!dataHoraInicio)                            erros.push('Data e horário de início ausentes.');
if (!duracaoMinutos || duracaoMinutos     <= 0) erros.push('Duração do procedimento inválida.');

if (erros.length > 0) {
  return { json: { sucesso: false, motivo: 'Erro nos dados: ' + erros.join(' ') } };
}

// ─── Formatador de Fuso Horário de São Paulo ──────────────────────────────────
const formatterSP = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
});

function getSPParts(dateObj) {
  const parts = formatterSP.formatToParts(dateObj);
  const m = {};
  parts.forEach(p => m[p.type] = p.value);
  return {
    ano: Number(m.year),
    mes: Number(m.month) - 1,
    dia: Number(m.day),
    hora: Number(m.hour === '24' ? '0' : m.hour),
    minuto: Number(m.minute)
  };
}

if (!dataHoraInicio.includes('Z') && !dataHoraInicio.includes('+') && !dataHoraInicio.match(/-\d{2}:\d{2}$/)) {
  if (dataHoraInicio.length === 16) dataHoraInicio += ':00';
  dataHoraInicio += '-03:00';
}

const inicio = new Date(dataHoraInicio);
if (isNaN(inicio.getTime())) {
  return { json: { sucesso: false, motivo: 'Formato de data/hora inválido.' } };
}

const inicioParts = getSPParts(inicio);
const isoDateStr = `${inicioParts.ano}-${String(inicioParts.mes + 1).padStart(2, '0')}-${String(inicioParts.dia).padStart(2, '0')}`;
const dataFormatadaStr = `${String(inicioParts.dia).padStart(2, '0')}/${String(inicioParts.mes + 1).padStart(2, '0')}/${inicioParts.ano}`;

// 🇧🇷 1. Cálculo Automático de Feriados Nacionais Brasileiros
function getPascoa(y) {
  const a = y % 19, b = Math.floor(y / 100), c = y % 100;
  const d = Math.floor(b / 4), e = b % 4, f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3), h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4), k = c % 4, L = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * L) / 451);
  const month = Math.floor((h + L - 7 * m + 114) / 31);
  const day = ((h + L - 7 * m + 114) % 31) + 1;
  return new Date(y, month - 1, day);
}

function obterFeriadosBR(y) {
  const feriados = {};
  feriados[`${y}-01-01`] = 'Ano Novo (Confraternização Universal)';
  feriados[`${y}-04-21`] = 'Tiradentes';
  feriados[`${y}-05-01`] = 'Dia do Trabalho';
  feriados[`${y}-09-07`] = 'Independência do Brasil';
  feriados[`${y}-10-12`] = 'Nossa Senhora Aparecida';
  feriados[`${y}-11-02`] = 'Finados';
  feriados[`${y}-11-15`] = 'Proclamação da República';
  feriados[`${y}-11-20`] = 'Dia da Consciência Negra';
  feriados[`${y}-12-25`] = 'Natal';

  const pascoa = getPascoa(y);
  const sextaSanta = new Date(pascoa); sextaSanta.setDate(pascoa.getDate() - 2);
  feriados[`${y}-${String(sextaSanta.getMonth() + 1).padStart(2, '0')}-${String(sextaSanta.getDate()).padStart(2, '0')}`] = 'Sexta-feira Santa';

  const carnavalSeg = new Date(pascoa); carnavalSeg.setDate(pascoa.getDate() - 48);
  feriados[`${y}-${String(carnavalSeg.getMonth() + 1).padStart(2, '0')}-${String(carnavalSeg.getDate()).padStart(2, '0')}`] = 'Carnaval';

  const carnavalTer = new Date(pascoa); carnavalTer.setDate(pascoa.getDate() - 47);
  feriados[`${y}-${String(carnavalTer.getMonth() + 1).padStart(2, '0')}-${String(carnavalTer.getDate()).padStart(2, '0')}`] = 'Carnaval';

  const corpus = new Date(pascoa); corpus.setDate(pascoa.getDate() + 60);
  feriados[`${y}-${String(corpus.getMonth() + 1).padStart(2, '0')}-${String(corpus.getDate()).padStart(2, '0')}`] = 'Corpus Christi';

  return feriados;
}

const feriadosAno = obterFeriadosBR(inicioParts.ano);
if (feriadosAno[isoDateStr]) {
  const nomeFeriado = feriadosAno[isoDateStr];
  return {
    json: {
      sucesso: false,
      motivo: `O estabelecimento estará fechado na data ${dataFormatadaStr} por conta do feriado nacional (${nomeFeriado}).`
    }
  };
}

// 🔒 2. Trava de Datas Bloqueadas no cadastro
const datasBloqStr = String(dados.datas_bloqueadas || '');
if (datasBloqStr.includes(isoDateStr) || datasBloqStr.includes(dataFormatadaStr)) {
  return {
    json: {
      sucesso: false,
      motivo: `O estabelecimento estará fechado na data ${dataFormatadaStr} (data bloqueada).`
    }
  };
}

// 🔒 3. Trava de Feriado / Bloqueio no Google Calendar
const palavrasChaveBloqueio = ['feriado', 'fechado', 'bloqueado', 'folga', 'recesso', 'independência', 'independencia', 'não atende', 'nao atende', 'sem atendimento'];

const ehFeriadoOuBloqueadoGC = todosEventos.some(ev => {
  if (ev.status === 'cancelled') return false;

  const summary = (ev.summary || '').toLowerCase();
  const desc = (ev.description || '').toLowerCase();
  const temPalavraChave = palavrasChaveBloqueio.some(p => summary.includes(p) || desc.includes(p));

  if (ev.start && ev.start.date) {
    const sDate = ev.start.date;
    const eDate = ev.end?.date || sDate;
    if (isoDateStr >= sDate && isoDateStr < eDate) return true;
    if (sDate === isoDateStr) return true;
  }

  if (temPalavraChave) {
    if (ev.start?.dateTime) {
      const sParts = getSPParts(new Date(ev.start.dateTime));
      if (sParts.ano === inicioParts.ano && sParts.mes === inicioParts.mes && sParts.dia === inicioParts.dia) {
        return true;
      }
    }
  }

  return false;
});

if (ehFeriadoOuBloqueadoGC) {
  return {
    json: {
      sucesso: false,
      motivo: `O estabelecimento estará fechado na data ${dataFormatadaStr} por conta de feriado ou bloqueio na agenda.`
    }
  };
}

const agoraParts = getSPParts(new Date());

const inicioTimestamp = Date.UTC(inicioParts.ano, inicioParts.mes, inicioParts.dia, inicioParts.hora, inicioParts.minuto);
const agoraTimestamp  = Date.UTC(agoraParts.ano, agoraParts.mes, agoraParts.dia, agoraParts.hora, agoraParts.minuto);

if (inicioTimestamp < agoraTimestamp) {
  return {
    json: {
      sucesso: false,
      motivo: 'Não é possível realizar agendamentos para datas ou horários que já passaram. Escolha uma data futura.'
    }
  };
}

if (inicioTimestamp < agoraTimestamp + 30 * 60000) {
  return {
    json: {
      sucesso: false,
      motivo: 'Agendamentos exigem uma antecedência mínima de 30 minutos a partir do horário atual. Escolha um horário mais tarde.'
    }
  };
}

if (![0, 30].includes(inicioParts.minuto)) {
  return { json: { sucesso: false, motivo: 'O horário não segue a grade de :00 ou :30.' } };
}

const dateSPForDay = new Date(Date.UTC(inicioParts.ano, inicioParts.mes, inicioParts.dia, 12, 0, 0));
let diaSemana = dateSPForDay.getUTCDay();
if (diaSemana === 0) diaSemana = 7;

function paraMinutos(hhmm) {
  if (!hhmm) return 0;
  const [h, m] = String(hhmm).split(':').map(Number);
  return h * 60 + m;
}

function obterHorariosDoDia(diaSem, d) {
  let hPorDia = d.horarios_por_dia;
  if (typeof hPorDia === 'string') {
    try { hPorDia = JSON.parse(hPorDia); } catch(e) {}
  }

  const mapaVariantes = {
    1: ['1', 'segunda', 'segunda-feira', 'segunda_feira'],
    2: ['2', 'terca', 'terça', 'terca-feira', 'terça-feira', 'terca_feira', 'terça_feira'],
    3: ['3', 'quarta', 'quarta-feira', 'quarta_feira'],
    4: ['4', 'quinta', 'quinta-feira', 'quinta_feira'],
    5: ['5', 'sexta', 'sexta-feira', 'sexta_feira'],
    6: ['6', 'sabado', 'sábado', 'sabado_feira'],
    7: ['7', 'domingo']
  };

  const chavesProcurar = mapaVariantes[diaSem] || [String(diaSem)];

  let configDia = null;
  if (hPorDia && typeof hPorDia === 'object') {
    const chavesObjeto = Object.keys(hPorDia);
    for (const key of chavesObjeto) {
      const keyNorm = key.trim().toLowerCase();
      if (chavesProcurar.some(varKey => varKey === keyNorm)) {
        configDia = hPorDia[key];
        break;
      }
    }
  }

  if (configDia === false || (configDia && configDia.fechado === true)) {
    return { aberto: false };
  }

  if (configDia && typeof configDia === 'object') {
    return {
      aberto: true,
      manhaIni: configDia.manha_inicio || configDia.manha?.[0] || d.turno_manha_inicio || '08:00',
      manhaFim: configDia.manha_fim    || configDia.manha?.[1] || d.turno_manha_fim    || '12:00',
      tardeIni: configDia.tarde_inicio || configDia.tarde?.[0] || d.turno_tarde_inicio || '13:00',
      tardeFim: configDia.tarde_fim    || configDia.tarde?.[1] || d.turno_tarde_fim    || '19:00',
      semManha: configDia.sem_manha === true || configDia.manha === null,
      semTarde: configDia.sem_tarde === true || configDia.tarde === null
    };
  }

  return {
    aberto: true,
    manhaIni: d.turno_manha_inicio || '08:00',
    manhaFim: d.turno_manha_fim    || '12:00',
    tardeIni: d.turno_tarde_inicio || '13:00',
    tardeFim: d.turno_tarde_fim    || '19:00',
    semManha: false,
    semTarde: false
  };
}

const horDia = obterHorariosDoDia(diaSemana, dados);

if (!horDia.aberto) {
  return { json: { sucesso: false, motivo: 'O estabelecimento não atende neste dia da semana.' } };
}

const inicioMin = inicioParts.hora * 60 + inicioParts.minuto;
const fimDate = new Date(inicio.getTime() + duracaoMinutos * 60000);
const fimParts = getSPParts(fimDate);
const fimMinCalc = fimParts.hora * 60 + fimParts.minuto;

const manhaIniMin = paraMinutos(horDia.manhaIni);
const manhaFimMin = paraMinutos(horDia.manhaFim);
const tardeIniMin = paraMinutos(horDia.tardeIni);
const tardeFimMin = paraMinutos(horDia.tardeFim);

const cabeNaManha = !horDia.semManha && inicioMin >= manhaIniMin && fimMinCalc <= manhaFimMin;
const cabeNaTarde = !horDia.semTarde && inicioMin >= tardeIniMin && fimMinCalc <= tardeFimMin;

if (!cabeNaManha && !cabeNaTarde) {
  return { json: { sucesso: false, motivo: 'O horário está fora do expediente do dia ou ultrapassa o fim do turno.' } };
}

function formatISOWithOffset(dateObj) {
  const sp = getSPParts(dateObj);
  const yyyy = sp.ano;
  const mm = String(sp.mes + 1).padStart(2, '0');
  const dd = String(sp.dia).padStart(2, '0');
  const hh = String(sp.hora).padStart(2, '0');
  const mi = String(sp.minuto).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}T${hh}:${mi}:00-03:00`;
}

return {
  json: {
    sucesso:              true,
    titulo_evento:        `${nomeCliente}, ${procedimento}`,
    data_hora_inicio_iso: formatISOWithOffset(inicio),
    data_hora_fim_iso:    formatISOWithOffset(fimDate),
    descricao_evento:     `Telefone: ${telefone}${observacoes ? ' | Observações: ' + observacoes : ''}`,
    calendar_id:          dados.calendar_id || dados.google_calendar_id || 'seu_email@dominio.com',
    google_access_token:  dados.google_access_token
  }
};
